{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret mangler kernen i reglen: journalmateriale fra egen læge, speciallæge, hospital eller ambulant klinik. Det erstatter dette med krav om en lægeerklæring, en funktionsevnevurdering og en prognose. Disse krav fremgår ikke af kilderne og fremstilles som obligatoriske ('skal som minimum'). Epikrise/afslutningsbrev nævnes ikke."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Ingen af de tre kritiske elementer er klart dækket. Journalmateriale fra de nævnte behandlertyper er kun delvist antydet ('journalnotater'). Kravet om, at materialet skal beskrive den varige funktionsnedsættelse, er ikke formuleret korrekt. Epikrise eller afslutningsbrev som udgangspunkt ved afsluttet behandling mangler helt."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret forholder sig til spørgsmålet om lægelig dokumentation ved afsluttet behandling. Indholdet er delvist forkert, men er ikke irrelevant fyld."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde som lov, bestemmelse eller vejledning."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer flere krav uden støtte i materialet: obligatorisk lægeerklæring udarbejdet af speciallæge eller praktiserende læge, funktionsevnevurdering, prognose, og at dokumentationen skal være dateret efter behandlingens afslutning. Kilderne kræver kun aktualitet, journaler og oplysninger om arten og graden."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Forbeholdet 'som udgangspunkt' for epikrise/afslutningsbrev ved afsluttet behandling er ikke bevaret, fordi elementet er udeladt. Svaret nævner heller ikke, at dokumentets titel ikke i sig selv afgør tilstrækkeligheden."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er internt sammenhængende: det opregner dokumentationselementer, understreger aktualitet og anbefaler at tale med en læge. Der er ingen indre modsigelser, selvom indholdet er juridisk forkert."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret bruger 'skal' og 'som minimum' om krav, der ikke er i kilderne (lægeerklæring, funktionsevnevurdering, prognose). Dermed gøres ikke-eksisterende krav absolutte. Kildens 'som udgangspunkt' om epikrise er ikke gengivet."}
  },
  "xhaile_coverage": {
    "A30": {"label": "no", "reason": "Svaret nævner ikke, at dokumentationen som udgangspunkt også indeholder epikrise eller afslutningsbrev, når behandlingsforløbet er afsluttet."},
    "A32": {"label": "no", "reason": "Epikrise eller afslutningsbrev som del af dokumentationen nævnes slet ikke."}
  },
  "overall_notes": "Svaret er generisk og ukildebaseret. Det rammer ikke minimumskravet om journaler og nævner ikke epikrise eller afslutningsbrev. Det opfinder lægeerklærings-, funktionsevne- og prognosekrav. Spørgsmålet er dog besvaret i emnet, og svaret er internt sammenhængende."
}

